"use client"

import Link from "next/link"
import { BookOpen, ArrowRight, User, LogOut } from "lucide-react"
import { useTranslations } from "next-intl"
import { Button } from "@/components/ui/button"
import { LanguageSwitcher } from "@/components/ui/language-switcher"
import { useAuth } from "@/components/auth-context"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"

export function Navbar() {
  const t = useTranslations()
  const { user, isAuthenticated, logout } = useAuth()

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 border-b border-slate-200/60 bg-white/90 backdrop-blur-xl">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 ltr-flex">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-2 group ltr-flex">
            <div className="p-1.5 bg-gradient-to-r from-sky-500 to-cyan-500 rounded-lg group-hover:shadow-lg group-hover:shadow-sky-500/25 transition-shadow">
              <BookOpen className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-bold bg-gradient-to-r from-sky-600 to-cyan-600 bg-clip-text text-transparent">
              {t("nav.brand")}
            </span>
          </Link>

          {/* Links */}
          <div className="hidden md:flex items-center gap-6 text-sm font-medium text-slate-600">
            {isAuthenticated && (
              <>
                <Link href="/courses" className="hover:text-sky-600 transition-colors">
                  {t("nav.courses") || "Courses"}
                </Link>
                <Link href="/dashboard" className="hover:text-sky-600 transition-colors">
                  {t("nav.dashboard") || "Dashboard"}
                </Link>
                {user?.role === 'INSTRUCTOR' && (
                  <Link href="/instructor" className="hover:text-sky-600 transition-colors">
                    {t("nav.instructor") || "Instructor"}
                  </Link>
                )}
                <Link href="/my-courses" className="hover:text-sky-600 transition-colors">
                  {t("nav.myLearning") || "My Learning"}
                </Link>
              </>
            )}
          </div>

          {/* Auth buttons */}
          <div className="flex items-center gap-3 ltr-flex">
            <LanguageSwitcher />
            
            {isAuthenticated ? (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" className="relative h-8 w-8 rounded-full">
                    <Avatar className="h-8 w-8">
                      <AvatarImage src="/avatars/01.png" alt={user?.firstName} />
                      <AvatarFallback>{user?.firstName?.[0]}{user?.lastName?.[0]}</AvatarFallback>
                    </Avatar>
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent className="w-56" align="end" forceMount>
                  <DropdownMenuLabel className="font-normal">
                    <div className="flex flex-col space-y-1">
                      <p className="text-sm font-medium leading-none">{user?.firstName} {user?.lastName}</p>
                      <p className="text-xs leading-none text-muted-foreground">
                        {user?.email}
                      </p>
                    </div>
                  </DropdownMenuLabel>
                  <DropdownMenuSeparator />
                  <Link href="/profile">
                    <DropdownMenuItem>
                      <User className="mr-2 h-4 w-4" />
                      <span>{t("common.profile") || "Profile"}</span>
                    </DropdownMenuItem>
                  </Link>
                  <DropdownMenuItem onClick={logout}>
                    <LogOut className="mr-2 h-4 w-4" />
                    <span>{t("common.signOut") || "Sign out"}</span>
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <>
                <Button variant="ghost" size="sm" asChild>
                  <Link href="/login">
                    {t("common.signIn")}
                  </Link>
                </Button>
                <Button size="sm" asChild>
                  <Link href="/register">
                    {t("common.getStarted")}
                    <ArrowRight className="w-4 h-4 rtl:rotate-180" />
                  </Link>
                </Button>
              </>
            )}
          </div>
        </div>
      </div>
    </nav>
  )
}
